+++ b/tmp/sv-8dff39f1d5704c13a2008912d4f30037/Components/Pages/Chat/ChatPage.razor
@@ -1,0 +1,200 @@
+@page "/chat"
+@layout ChatLayout
+@rendermode InteractiveServer
+@using sv_8dff39f1d5704c13a2008912d4f30037.Services
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-container">
+    <div class="sidebar-panel">
+        <ChannelSidebar Channels="channels"
+                        SelectedChannelId="selectedChannelId"
+                        OnChannelSelected="SelectChannelAsync" />
+    </div>
+
+    <div class="main-panel @(threadOpen ? "" : "expanded")">
+        <MessageArea @ref="messageAreaRef"
+                     Messages="messages"
+                     CurrentChannel="selectedChannel"
+                     ThreadSummaries="threadSummaries"
+                     IsLoadingMore="isLoadingMore"
+                     OnLoadMore="LoadMoreMessagesAsync"
+                     OnSendMessage="SendMessageAsync"
+                     OnOpenThread="OpenThreadAsync"
+                     OnReact="AddReactionAsync" />
+    </div>
+
+    @if (threadOpen)
+    {
+        <div class="thread-panel-container">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadReplies"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReplyAsync" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private Dictionary<int, ThreadSummary> threadSummaries = [];
+    private Channel? selectedChannel;
+    private int? selectedChannelId;
+
+    private bool threadOpen;
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = [];
+
+    private bool isLoadingMore;
+    private const int PageSize = 30;
+
+    private MessageArea? messageAreaRef;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannelAsync(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannelAsync(int channelId)
+    {
+        if (selectedChannelId == channelId) return;
+
+        selectedChannelId = channelId;
+        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messages = [];
+        threadSummaries = [];
+        CloseThread();
+
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        await ChatService.MarkChannelReadAsync(channelId);
+        await BuildThreadSummariesAsync();
+
+        // Update unread count locally
+        var idx = channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            channels[idx] = channels[idx] with { UnreadCount = 0 };
+        }
+
+        StateHasChanged();
+        if (messageAreaRef is not null)
+        {
+            await messageAreaRef.ScrollToBottomAsync();
+        }
+    }
+
+    private async Task LoadMoreMessagesAsync()
+    {
+        if (isLoadingMore || selectedChannelId is null) return;
+
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            await BuildThreadSummariesAsync();
+        }
+
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessageAsync(string content)
+    {
+        if (selectedChannelId is null) return;
+
+        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
+        messages.Add(msg);
+        StateHasChanged();
+
+        if (messageAreaRef is not null)
+        {
+            await messageAreaRef.ScrollToBottomAsync();
+        }
+    }
+
+    private async Task OpenThreadAsync(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+
+        var allThreadMessages = await ChatService.GetThreadAsync(messageId);
+        threadReplies = allThreadMessages.Where(m => m.Id != messageId).ToList();
+        threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task SendThreadReplyAsync(string content)
+    {
+        if (threadRootMessage is null || selectedChannelId is null) return;
+
+        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+
+        // Update thread summary
+        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
+            threadRootMessage.Id,
+            threadReplies.Count,
+            reply.SentAt
+        );
+    }
+
+    private async Task AddReactionAsync((int MessageId, string Emoji) reaction)
+    {
+        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
+
+        // Refresh messages to reflect updated reactions
+        if (selectedChannelId is not null)
+        {
+            messages = await ChatService.GetMessagesAsync(selectedChannelId.Value, 0, messages.Count);
+        }
+    }
+
+    private async Task BuildThreadSummariesAsync()
+    {
+        // Build thread summaries from messages that have replies
+        var rootIds = messages
+            .Where(m => m.ReplyToId is not null)
+            .Select(m => m.ReplyToId!.Value)
+            .Distinct()
+            .ToList();
+
+        foreach (var rootId in rootIds)
+        {
+            if (!threadSummaries.ContainsKey(rootId))
+            {
+                try
+                {
+                    var thread = await ChatService.GetThreadAsync(rootId);
+                    var replies = thread.Where(m => m.Id != rootId).ToList();
+                    if (replies.Count > 0)
+                    {
+                        threadSummaries[rootId] = new ThreadSummary(
+                            rootId,
+                            replies.Count,
+                            replies.Max(r => r.SentAt)
+                        );
+                    }
+                }
+                catch
+                {
+                    // Thread data unavailable — skip
+                }
+            }
+        }
+    }
+}
+

